let encode_consignment (str_len : (string -> bigint)) (c : ref_consignment) : value<'raw, 'flt> =
  (VArr (((VStr ((c).reference, (str_len (c).reference))) :: ((encode_address str_len (c).origin) :: ((VInt ((c).weight, Bits32)) :: ((VBool ((c).urgent)) :: []))))))

let decode_address (custard_eta : value<'raw, 'flt>) : outcome<ref_address> =
  (op_Bar_Greater_Greater (op_Bar_Greater_Greater (op_Bar_Greater_Greater (succeed (fun (l : string) (p : string) (c : string) -> { ref_address.line1 = l;
                                                                                                                                    postcode = p;
                                                                                                                                    country = c })) (field "Line1" (0I) as_string)) (field "Postcode" (1I) as_string)) (field "Country" (2I) as_string) custard_eta)

let reinterpret_i32 (n : bigint) : bigint =
  (if (Prims.op_Less n (-2147483648I)) then (0I) else (if (Prims.op_Less_Equals n (2147483647I)) then n else (if (Prims.op_Less_Equals n (4294967295I)) then (Prims.op_Minus n (4294967296I)) else (0I))))

let decode_consignment (custard_eta : value<'raw, 'flt>) : outcome<ref_consignment> =
  (op_Bar_Greater_Greater (op_Bar_Greater_Greater (op_Bar_Greater_Greater (op_Bar_Greater_Greater (succeed (fun (r : string) (o : ref_address) (w : bigint) (u : bool) -> { ref_consignment.reference = r;
                                                                                                                                                                            origin = o;
                                                                                                                                                                            weight = (reinterpret_i32 w);
                                                                                                                                                                            urgent = u })) (field "Reference" (0I) as_string)) (field "Origin" (1I) decode_address)) (field "Weight" (2I) as_int32)) (field "Urgent" (3I) as_bool) custard_eta)

type ref_status =
  | Planned
  | Delayed of string * bigint
  | Arrived of bigint


let encode_status (str_len : (string -> bigint)) (s : ref_status) : value<'raw, 'flt> =
  (match s with
   | Planned -> (VArr (((VInt ((0I), Fixnum)) :: [])))
   | (Delayed (reason, minutes)) -> (VArr (((VInt ((1I), Fixnum)) :: ((VArr (((VStr (reason, (str_len reason))) :: ((VInt (minutes, Bits32)) :: [])))) :: []))))
   | (Arrived (at)) -> (VArr (((VInt ((2I), Fixnum)) :: ((VInt (at, Bits32)) :: [])))))

type ref_leg = {
  hop : pair<bigint, string>;
  status : ref_status;
}

let encode_leg (str_len : (string -> bigint)) (l : ref_leg) : value<'raw, 'flt> =
  (VArr (((VArr (((VInt (((l).hop : pair<_, _>).first, Bits32)) :: ((VStr (((l).hop : pair<_, _>).second, (str_len ((l).hop : pair<_, _>).second))) :: [])))) :: ((encode_status str_len (l).status) :: []))))

let decode_status (custard_eta : value<'raw, 'flt>) : outcome<ref_status> =
  (union "RefStatus" (fun (tag : bigint) -> (if (tag = (0I)) then (OSome ((case0 Planned))) else (if (tag = (1I)) then (OSome ((fields (2I) (op_Bar_Greater_Greater (op_Bar_Greater_Greater (succeed (fun (r : string) (m : bigint) -> (Delayed (r, (reinterpret_i32 m))))) (field "reason" (0I) as_string)) (field "minutes" (1I) as_int32))))) else (if (tag = (2I)) then (OSome ((payload (map (fun (a : bigint) -> (Arrived ((reinterpret_i32 a)))) as_int32)))) else ONone)))) custard_eta)

let decode_leg (custard_eta : value<'raw, 'flt>) : outcome<ref_leg> =
  (op_Bar_Greater_Greater (op_Bar_Greater_Greater (succeed (fun (h : pair<bigint, string>) (s : ref_status) -> { ref_leg.hop = h;
                                                                                                                 status = s })) (field "Hop" (0I) (tuple2 (map reinterpret_i32 as_int32) as_string))) (field "Status" (1I) decode_status) custard_eta)

